/**
 * Narrative section identity. A grant's ProjectNarrativeSections each carry a stable `id`; an
 * application keys its section text by that id and keeps `section_order` ([{id, name}]) beside it.
 *
 * An id is the slug of the section's name when first seen, so a summary written before ids
 * existed derives the same ids on every read, and an application keyed by name maps onto them.
 * Mirrored in shared/draft_sections.py and the UI's application-sections.ts; the shared
 * fixture test/fixtures/section-ids.json pins all three.
 */

const MAX_SLUG_LENGTH = 64;

export function sectionSlug(name) {
  const slug = String(name ?? "")
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, MAX_SLUG_LENGTH)
    .replace(/-+$/g, "");
  return slug || "section";
}

export function uniqueSectionId(base, used) {
  let id = base;
  for (let n = 2; used.has(id); n += 1) id = `${base}-${n}`;
  used.add(id);
  return id;
}

/** Copies of `items` ({item, description, id?}) with a unique `id` on each, in their order. */
export function withSectionIds(items) {
  if (!Array.isArray(items)) return [];
  const used = new Set();
  const kept = items.map((entry) => {
    const id = typeof entry?.id === "string" && entry.id.trim() !== "" ? entry.id.trim() : null;
    if (!id || used.has(id)) return null;
    used.add(id);
    return id;
  });
  return items.map((entry, index) => ({
    ...entry,
    id: kept[index] ?? uniqueSectionId(sectionSlug(entry?.item), used),
  }));
}

/**
 * An application's section text keyed by id, with its order. A row from before ids existed
 * (no section_order) is keyed by name; each name maps to the outline section of that name,
 * else to its own slug. The order is the outline's, then any other sections in their stored order.
 */
export function normalizeApplicationSections(sections, sectionOrder, outline = []) {
  const text = sections && typeof sections === "object" ? sections : {};
  const outlineRefs = (outline || []).filter((ref) => ref && typeof ref.id === "string");

  if (Array.isArray(sectionOrder)) {
    const order = sectionOrder.filter((ref) => ref && typeof ref.id === "string");
    return { sections: { ...text }, order: mergeOrder(outlineRefs, order) };
  }

  const used = new Set();
  const byName = new Map();
  for (const ref of outlineRefs) if (!byName.has(ref.name)) byName.set(ref.name, ref.id);
  const bySlug = new Map();
  for (const ref of outlineRefs) {
    const slug = sectionSlug(ref.name);
    if (!bySlug.has(slug)) bySlug.set(slug, ref.id);
  }

  const converted = {};
  const extras = [];
  const reserved = new Set(outlineRefs.map((r) => r.id));
  for (const [name, value] of Object.entries(text)) {
    let id = reserved.has(name) ? name : byName.get(name);
    if (!id || used.has(id)) id = bySlug.get(sectionSlug(name));
    if (!id || used.has(id)) {
      id = uniqueSectionId(sectionSlug(name), new Set([...used, ...reserved]));
      extras.push({ id, name });
    }
    used.add(id);
    converted[id] = value;
  }
  return { sections: converted, order: mergeOrder(outlineRefs.map(({ id, name }) => ({ id, name })), extras) };
}

function mergeOrder(first, second) {
  const seen = new Set();
  const out = [];
  for (const ref of [...first, ...second]) {
    if (seen.has(ref.id)) continue;
    seen.add(ref.id);
    out.push({ id: ref.id, name: typeof ref.name === "string" ? ref.name : ref.id });
  }
  return out;
}

/** [{name, content}] for an export: `sectionOrder` order when given, else the map's own order. */
export function orderedSections(draftData) {
  const sections = draftData?.sections && typeof draftData.sections === "object" ? draftData.sections : {};
  if (!Array.isArray(draftData?.sectionOrder)) {
    return Object.entries(sections).map(([name, content]) => ({ name, content }));
  }
  const seen = new Set();
  const out = [];
  for (const ref of draftData.sectionOrder) {
    if (!ref || typeof ref.id !== "string" || seen.has(ref.id) || !(ref.id in sections)) continue;
    seen.add(ref.id);
    out.push({ name: typeof ref.name === "string" && ref.name ? ref.name : ref.id, content: sections[ref.id] });
  }
  for (const [id, content] of Object.entries(sections)) {
    if (!seen.has(id)) out.push({ name: id, content });
  }
  return out;
}
